// Verifies the HMAC signature the website sends.
// Set ENQUIRY_WEBHOOK_SECRET on the website to the same value you put in
// the n8n credential/variable below, then this node proves the request is
// genuinely from your site and not someone who guessed the URL.

const crypto = require('crypto');

// TODO: replace with your shared secret (or read from an n8n variable).
const SECRET = $env.SYNCTECH_WEBHOOK_SECRET || '';
const MAX_AGE_SECONDS = 300;

const item = $input.first();
const headers = item.json.headers || {};
const signature = headers['x-synctech-signature'] || '';
const timestamp = headers['x-synctech-timestamp'] || '';

// The raw body string exactly as sent — do not re-serialise, whitespace matters.
const rawBody = item.binary?.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body);

if (!SECRET) {
  // No secret configured: pass through, but make it visible.
  return [{ json: { ...JSON.parse(rawBody), _verified: false, _reason: 'no secret configured' } }];
}

if (!signature || !timestamp) {
  throw new Error('Missing signature headers — request did not come from the website.');
}

const age = Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp));
if (age > MAX_AGE_SECONDS) {
  throw new Error(`Signature too old (${age}s) — possible replay.`);
}

const expected = 'sha256=' + crypto
  .createHmac('sha256', SECRET)
  .update(`${timestamp}.${rawBody}`)
  .digest('hex');

const a = Buffer.from(signature);
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Invalid signature — rejecting request.');
}

return [{ json: { ...JSON.parse(rawBody), _verified: true } }];

// Simple, explainable lead triage. No AI needed for this part —
// it is deterministic, free, and you can reason about why a lead was routed.

const HIGH_VALUE = ['$15,000 – $50,000', '$50,000+', 'Ongoing monthly retainer'];

return $input.all().map((item) => {
  const d = item.json;
  const highValue = HIGH_VALUE.includes(d.budget);
  const hasCompany = Boolean(d.companyName && d.companyName.trim());
  const detailed = (d.description || '').length > 200;
  const flagged = Boolean(d.warning);

  // 0–100. Tune the weights to match how you actually qualify work.
  let score = 40;
  if (highValue) score += 30;
  if (hasCompany) score += 15;
  if (detailed) score += 15;
  if (flagged) score -= 30;

  score = Math.max(0, Math.min(100, score));

  return {
    json: {
      ...d,
      priority: score >= 75 ? 'high' : score >= 50 ? 'normal' : 'low',
      score,
      reasons: [
        highValue ? 'budget in target range' : 'budget below target or unspecified',
        hasCompany ? 'named company' : 'no company given',
        detailed ? 'detailed description' : 'short description',
        flagged ? `flagged: ${d.warning}` : 'no spam signals',
      ],
    },
  };
});
